import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.cyF4XceO.js";const h=JSON.parse('{"title":"0055 — Specification release needs only the normative source","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0055-specification-release-needs-only-normative-source.md","filePath":"spec/decisions/0055-specification-release-needs-only-normative-source.md"}'),n={name:"spec/decisions/0055-specification-release-needs-only-normative-source.md"};function r(s,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_0055-—-specification-release-needs-only-the-normative-source" tabindex="-1">0055 — Specification release needs only the normative source <a class="header-anchor" href="#_0055-—-specification-release-needs-only-the-normative-source" aria-label="Permalink to &quot;0055 — Specification release needs only the normative source&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-24</li><li>Supersedes: decisions 0052 and 0053 only where they require candidate-corpus and reference-Host evidence for Specification 1.0</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Takoform is a specification project. Its candidate Forms, reference Host, official Terraform Provider, and product integrations are useful ways to test and demonstrate that specification, but they are implementations and adoption evidence. Requiring every current family corpus and the repository-owned reference Host to pass before the Specification can be numbered makes the sample distribution an authority over the standard it is meant to implement.</p><p>The separation established by decisions 0052 and 0053 remains correct: Provider, Host, backend, production, Takoserver, Takosumi, signer, and operator facts do not govern the Specification. The remaining problem is that the old three-prerequisite rule still gave Takoform&#39;s own candidate catalog and reference implementation that authority.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Specification 1.0 has one release prerequisite: <code>specification-source-snapshot</code>.</p><p>The snapshot binds one reachable committed revision of the normative <code>spec/</code> tree by its exact path set and content digests. The portable repository gate continues to validate the schemas and internal references in that tree. The publication record itself is excluded from its own digest.</p><p>The generated candidate-family index, Form Packages, Interface and Binding catalogs, conformance corpora, reference Host execution, official Provider, and external product evidence remain independently checkable. Missing or failing evidence in those classes does not block the Specification assertion and is not copied into a numbered Specification release.</p><p>This does not weaken an implementation&#39;s claims. A Host, Provider, Form Package, or product may claim only the exact conformance evidence it actually has. It also does not promote any current <code>0.x</code> FormRef, publish a package, release Provider 3, deploy a Host, or authorize production mutation.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The Specification can be numbered after its own normative bytes are committed and self-consistent. Reference conformance and all-family coverage remain valuable quality signals, but they are no longer release authority. The release ledger becomes smaller: it records the source commit and digest of the normative snapshot, while implementation streams keep their own evidence and cadence.</p>',12)])])}const u=a(n,[["render",r]]);export{h as __pageData,u as default};
